def ext(r,name,*keys):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k in ('valueDateTime','valueString','valueDate','valueCode'):
                if k in e: return e[k]
    return None
acc_by={}
spec_by_acc=collections.defaultdict(list)
for r in allr:
    if r['resourceType']=='Basic':
        acc_by[ext(r,'accession')]=r
for r in allr:
    if r['resourceType']=='Specimen':
        spec_by_acc[r.get('accessionIdentifier',{}).get('value')].append(r)
pat={}
for r in allr:
