    elif t=='Observation':
        sp=r.get('specimen',{}).get('reference','').split('/')[-1]
        spr=byid.get(sp)
        acc=r.get('identifier',[{}])[0].get('value')
        a=acc_by.get(acc)
        o.append(f"    {r['code']['text']} status={r['status']} collected={r.get('effectiveDateTime')} issued={r.get('issued')} value={r.get('valueString')!r}")
        if r.get('note'): o.append(f"    notes={[n.get('text') for n in r['note']]}")
        o.append(f"    acc={acc} specimen={sp}")
        if spr: o.append(f"      spec label: name={ext(spr,'label-name')} mrn={ext(spr,'label-mrn')} dob={ext(spr,'label-dob')} accId={spr.get('accessionIdentifier',{}).get('value')} collected={spr.get('collection',{}).get('collectedDateTime')} collector={spr.get('collection',{}).get('collector',{}).get('display')} subj={spr.get('subject',{}).get('reference')} note={[n.get('text') for n in spr.get('note',[])]}")
        if a: o.append(f"      accessioning {a['id']}: name={ext(a,'patient-name')} mrn={ext(a,'patient-mrn')} dob={ext(a,'patient-dob')} received={ext(a,'received')}")
        else: o.append(f"      accessioning: NONE for {acc}")
    elif t=='MedicationAdministration':
        o.append(f"    status={r['status']} when={r.get('effectiveDateTime')} med={r.get('medicationCodeableConcept',{}).get('text')} dosage={r.get('dosage',{}).get('text')} perf={[p.get('actor',{}).get('display') for p in r.get('performer',[])]} reason={r.get('statusReason')} note={[n.get('text') for n in r.get('note',[])]}")
    elif t=='MedicationDispense':
        o.append(f"    med={r.get('medicationCodeableConcept',{}).get('text')} qty={r.get('quantity')} daysSupply={r.get('daysSupply')} handed={r.get('whenHandedOver')} dosage={[d.get('text') for d in r.get('dosageInstruction',[])]} note={[n.get('text') for n in r.get('note',[])]}")
    elif t=='DocumentReference':
        o.append(f"    type={r.get('type',{}).get('text')} date={r.get('date')} author={[a.get('display') for a in r.get('author',[])]} role={ext(r,'author-role')} status={r.get('docStatus')}")
        o.append("    TEXT: "+r.get('description','').replace('\n','\n          '))
    elif t=='AllergyIntolerance':
        o.append(f"    {r.get('code',{}).get('text')} reaction={json.dumps(r.get('reaction'))} note={[n.get('text') for n in r.get('note',[])]}")
    elif t=='Task':
        o.append(f"    status={r['status']} code={r.get('code')} desc={r.get('description')} focus={r.get('focus')}")
    else: o.append("    "+json.dumps(r))
    return '\n'.join(o)
import sys
pats=json.load(open('patients.json'))['patients']
for p in pats:
    pid=p['patient']['id']
    if len(sys.argv)>1 and pid not in sys.argv[1:]: continue
    pp=p['patient']
    print('='*100)
    print(f"{pid} {pp['name'][0]['text']} dob={pp['birthDate']} mrn={pp['identifier'][0]['value']} gender={pp['gender']}")
    for e in p['episodes']: print(f"  EPISODE {e['id']} start={e['period']['start']}")
    for r in sorted(recs[pid],key=lambda r:(ext(r,'event-time') or '')):
        print(desc(r))
