import json,glob,collections
allr=[]
for f in glob.glob('export/*.ndjson'):
    for line in open(f): allr.append(json.loads(line))
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k in ('valueDateTime','valueString','valueDate','valueCode'): 
                if k in e: return e[k]
byid={r['id']:r for r in allr}
pats={r['id']:r for r in allr if r['resourceType']=='Patient'}
bymrn={p['identifier'][0]['value']:(p['id'],p['birthDate'],p['name'][0]['text']) for p in pats.values()}
acc={ext(r,'accession'):r for r in allr if r['resourceType']=='Basic'}
print("== observation identity check ==")
for o in [r for r in allr if r['resourceType']=='Observation']:
    subj=o['subject']['reference'].split('/')[1]
    p=pats[subj]
    sp=byid.get(o.get('specimen',{}).get('reference','').split('/')[-1])
    a=acc.get(o.get('identifier',[{}])[0].get('value'))
    probs=[]
    if sp is None: probs.append('NO SPECIMEN')
    else:
        if sp['subject']['reference'].split('/')[1]!=subj: probs.append('spec subject differs: '+sp['subject']['reference'])
        if ext(sp,'label-mrn')!=p['identifier'][0]['value'] or ext(sp,'label-dob')!=p['birthDate']:
            probs.append('spec label id=%s/%s'%(ext(sp,'label-mrn'),ext(sp,'label-dob')))
        if sp.get('accessionIdentifier',{}).get('value')!=o.get('identifier',[{}])[0].get('value'): probs.append('accession mismatch spec')
    if a is None: probs.append('NO ACCESSIONING')
    else:
        if ext(a,'patient-mrn')!=p['identifier'][0]['value'] or ext(a,'patient-dob')!=p['birthDate']:
            probs.append('acc entry id=%s/%s'%(ext(a,'patient-mrn'),ext(a,'patient-dob')))
    if probs:
        print(subj,p['name'][0]['text'],o['id'],o['code']['text'],o.get('effectiveDateTime'),'|',probs)
print("== specimens with no observation ==")
obspec={r.get('specimen',{}).get('reference','').split('/')[-1] for r in allr if r['resourceType']=='Observation'}
for s in [r for r in allr if r['resourceType']=='Specimen']:
    if s['id'] not in obspec: print(s['id'],s['subject']['reference'],ext(s,'label-name'),s['collection']['collectedDateTime'])
print("== accessioning entries not used by any observation ==")
used={r.get('identifier',[{}])[0].get('value') for r in allr if r['resourceType']=='Observation'}
for k,v in acc.items():
    if k not in used: print(k,ext(v,'patient-name'),ext(v,'patient-mrn'),ext(v,'patient-dob'),ext(v,'received'))
print("== non-final observations ==")
for o in [r for r in allr if r['resourceType']=='Observation' and r['status']!='final']:
    print(o['subject']['reference'],o['id'],o['code']['text'],o['status'],o.get('effectiveDateTime'),[n.get('text') for n in o.get('note',[])])
print("== tasks ==")
for t in [r for r in allr if r['resourceType']=='Task']: print(t['id'],t['status'],t.get('code'),t.get('for'))
