for s in [r for r in allr if r['resourceType']=='Specimen']:
    if s['id'] not in obspec: print(s['id'],s['subject']['reference'],ext(s,'label-name'),s['collection']['collectedDateTime'])
print("== accessioning entries not used by any observation ==")
used={r.get('identifier',[{}])[0].get('value') for r in allr if r['resourceType']=='Observation'}
for k,v in acc.items():
    if k not in used: print(k,ext(v,'patient-name'),ext(v,'patient-mrn'),ext(v,'patient-dob'),ext(v,'received'))
print("== non-final observations ==")
for o in [r for r in allr if r['resourceType']=='Observation' and r['status']!='final']:
    print(o['subject']['reference'],o['id'],o['code']['text'],o['status'],o.get('effectiveDateTime'),[n.get('text') for n in o.get('note',[])])
print("== tasks ==")
for t in [r for r in allr if r['resourceType']=='Task']: print(t['id'],t['status'],t.get('code'),t.get('for'))
